<sc-if value="{{isIn}}" hint-placeholder-val="{{ false }}">
<div data-n="Top line" style="display:flex;gap:var(--space-12);align-items:center">
<div style="flex:1 1 0;min-width:0;display:flex;flex-direction:column;gap:2px">
<h3 class="body-bold" style="margin:0;color:var(--text-primary)">JusPrin account</h3>
<sc-if value="{{isSignedIn}}" hint-placeholder-val="{{ false }}"><div style="display:flex;gap:var(--space-8);align-items:center"><span aria-hidden="true" style="box-sizing:border-box;flex:none;width:8px;height:8px;border-radius:50%;background:var(--status-success)"></span><span class="label" style="color:var(--text-secondary)">Signed in as {{email}}</span></div></sc-if>
<sc-if value="{{isUnavailable}}" hint-placeholder-val="{{ false }}"><div style="display:flex;gap:var(--space-8);align-items:center"><span aria-hidden="true" style="box-sizing:border-box;flex:none;width:8px;height:8px;border-radius:50%;background:var(--status-warning)"></span><span class="label" style="color:var(--text-primary)">Signed in as {{email}} · AI unavailable</span></div></sc-if>
</div>
<sc-if value="{{isSignedIn}}" hint-placeholder-val="{{ false }}"><button type="button" onClick="{{signOut}}" style="box-sizing:border-box;flex:none;display:flex;gap:6px;padding:6px var(--space-12);align-items:center;margin:0;border:none;cursor:pointer;font:inherit;background:transparent;border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle);color:var(--text-primary)"><span class="body-small" style="white-space:nowrap">Sign out</span></button></sc-if>
<sc-if value="{{isUnavailable}}" hint-placeholder-val="{{ false }}"><button type="button" onClick="{{retry}}" style="box-sizing:border-box;flex:none;display:flex;gap:6px;padding:6px var(--space-12);align-items:center;margin:0;border:none;cursor:pointer;font:inherit;background:transparent;border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle);color:var(--text-primary)"><span class="body-small" style="white-space:nowrap">Try again</span></button></sc-if>
</div>
<sc-if value="{{isUnavailable}}" hint-placeholder-val="{{ false }}"><div class="label" style="color:var(--text-secondary)">Your account and AI setup stay intact. Your own key or AI tool still works meanwhile.</div></sc-if>
</sc-if>
</div>
</x-dc>
<script type="text/x-dc" data-dc-script data-props='{"status":{"editor":"enum","options":["signedOut","waiting","code","ended","signedIn","unavailable"],"default":"signedOut"},"email":{"editor":"text","default":"alex@example.com"},"onChange":{"editor":null},"$preview":{"width":560,"height":360}}'>
// The same sign-in form as first launch (Kenneth, 2026-11-07): Continue with
// Google, or an email that stays in the app with its emailed code or the
// password. The server's own sign-in page is never shown.
class Component extends DCLogic {
  componentWillUnmount() { clearTimeout(this._timer); }
  renderVals() {
    const st = this.state || {};
    const controlled = typeof this.props.onChange === 'function';
    const status = controlled ? (this.props.status ?? 'signedOut') : (st.status ?? this.props.status ?? 'signedOut');
    const set = (next) => { if (controlled) this.props.onChange(next); else this.setState({ status: next }); };
    const go = (next) => () => {
      clearTimeout(this._timer);
      set(next);
      if (next === 'waiting' || next === 'code') this._timer = setTimeout(() => set('signedIn'), 2500);
    };
    return {
      email: this.props.email ?? 'alex@example.com',
      isOut: status === 'signedOut' || status === 'waiting' || status === 'code',
      isOffer: status === 'signedOut',
      isEnded: status === 'ended',
      isWaiting: status === 'waiting',
      isCode: status === 'code',
      isIn: status === 'signedIn' || status === 'unavailable',
      isSignedIn: status === 'signedIn',
      isUnavailable: status === 'unavailable',
      google: go('waiting'),
      signUp: go('code'),
      cancel: go('signedOut'),
      signOut: go('signedOut'),
      retry: go('signedIn')
    };
  }
}
</script>
</body>
</html>

