content.content:
1	// The Agent's ways of connecting, drawn once for every surface that offers
2	// them: the JusPrin account block, one row per provider key, and one row per
3	// AI tool (canvas "JusPrin v2": Agent/Account Row, Agent/Provider Row,
4	// Agent/Your Own API Key and Agent/Tool Row, decided 2026-10-21). Preferences
5	// › Account holds the account; Preferences › BYOAI the keys and the tools.
6	
7	import { KeyboardEvent, RefObject, useEffect, useRef, useState } from 'react';
8	import { AccountStatusPayload, McpToolInfo, PageMessageType, SavedKeyInfo, SetupStatusPayload } from '../bridge/protocol';
9	import { SIGNUP_AFTER, SIGNUP_OFFER, SIGNUP_SCALE } from '../credits';
10	import { SignInActions, SignInButtons, SignInDoor } from './SignInDoor';
11	
12	// The page and the host ship in the same build, so this list and the host's
13	// setup_provider_supported() are two views of the same fact. The host still
14	// validates: an unsupported provider comes back as a visible setup error
15	// rather than a request that never answers.
16	export interface ProviderOption {
17	  id: string;
18	  label: string;
19	  // How the provider's keys start, for the placeholder and the locked field.
20	  prefix: string;
21	}
22	
23	export const PROVIDERS: ProviderOption[] = [
24	  { id: 'anthropic', label: 'Anthropic', prefix: 'sk-ant-' },
25	  { id: 'openai', label: 'OpenAI', prefix: 'sk-' },
26	  { id: 'openrouter', label: 'OpenRouter', prefix: 'sk-or-' },
27	];
28	
29	export function providerLabel(id: string | undefined): string {
30	  return PROVIDERS.find((provider) => provider.id === id)?.label ?? 'your provider';
31	}
32	
33	// The Agent page's own buttons, drawn in the shared sign-in.
34	const AGENT_BUTTONS: SignInButtons = { primary: 'primary', secondary: 'agent-row-action' };
35	
36	// The shared sign-in's controls, as the Agent page's bridge carries them out.
37	// Every window that signs in speaks the same messages.
38	export function accountSignInActions(send: (type: PageMessageType, payload: object) => void): SignInActions {
39	  return {
40	    google: () => send('account_sign_in', {}),
41	    email: (email) => send('account_email', { email }),
42	    sendCode: () => send('account_send_code', {}),
43	    code: (code) => send('account_code', { code }),
44	    password: (password) => send('account_password', { password }),
45	    cancel: () => send('account_cancel', {}),
46	    reopen: () => send('account_reopen', {}),
47	    openLink: (link) => send('account_open_link', { link }),
48	  };
49	}
50	
51	export interface AccountSignInProps {
52	  status: AccountStatusPayload;
53	  actions: SignInActions;
54	}
55	
56	// The sign-in every screen shares (SignInDoor), in a column of its own.
57	// `children` is what it says above the door while nothing has started.
58	export function AccountSignIn({ status, actions, children }: AccountSignInProps & { children?: React.ReactNode }) {
59	  return (
60	    <div className="account-sign-in">
61	      <SignInDoor phase={status.phase} email={status.email} error={status.error?.message} actions={actions}
62	        buttons={AGENT_BUTTONS}>
63	        {children}
64	      </SignInDoor>
65	    </div>
66	  );
67	}
68	
69	// The first-month offer, the headline wherever someone can sign in for the
70	// first time (canvas "JusPrin v2", boards 1a to 1c), over the sign-in itself.
71	// Signing up and signing in are one door: an address with no account gets
72	// one from its first code. `note` is what a surface adds under the offer.
73	// `freeAfter` adds what a free account gets after the month, for someone who
74	// has no plan yet; a v1 subscriber keeps theirs, so the welcome-back window
75	// leaves it out.
76	export function FirstMonthOffer({ note, freeAfter, status, actions }: AccountSignInProps & { note?: string; freeAfter?: boolean }) {
77	  return (
78	    <div className="credit-offer" data-testid="first-month-offer">
79	      <AccountSignIn status={status} actions={actions}>
80	        <div className="credit-offer-copy">
81	          <h2 className="credit-offer-title">{SIGNUP_OFFER}</h2>
82	          <p>{SIGNUP_SCALE}</p>
83	          {freeAfter && <p>{SIGNUP_AFTER}</p>}
84	          {note && <p className="credit-offer-note">{note}</p>}
85	        </div>
86	      </AccountSignIn>
87	    </div>
88	  );
89	}
90	
91	export interface AccountRowProps extends AccountSignInProps {
92	  // The signed-in account, from setup_keys; absent when signed out.
93	  account?: SavedKeyInfo;
94	  onSignOut: () => void;
95	}
96	
97	// The JusPrin account (canvas "JusPrin v2": Agent/Account Row): signed out,
98	// signed in, or signed in with a sign-in that has ended. Signing in, or in
99	// again, is the sign-in every screen shares.
100	export function AccountRow({ account, status, actions, onSignOut }: AccountRowProps) {
101	  if (!account) {
102	    return (
103	      <div className="agent-account-offer" data-testid="agent-account">
104	        <span className="agent-account-eyebrow">JusPrin account</span>
105	        <FirstMonthOffer freeAfter status={status} actions={actions} />
106	        {status.warning && <p className="agent-row-note">{status.warning}</p>}
107	      </div>
108	    );
109	  }
110	  if (account.rejected) {
111	    return (
112	      <div className="agent-account-offer" data-testid="agent-account">
113	        <div className="agent-row-copy">
114	          <h2 className="agent-account-title">JusPrin account</h2>
115	          <span className="agent-row-status agent-row-status--rejected" data-testid="agent-account-status">
116	            <span className="agent-row-status-label">
117	              <span className="jp-icon jp-icon-circle-alert" aria-hidden="true" />
118	              <span>Your sign-in for {account.account || 'this account'} has ended</span>
119	            </span>
120	          </span>
121	        </div>
122	        <p className="agent-row-note">Sign in again to keep using AI with your JusPrin account.</p>
123	        <AccountSignIn status={status} actions={actions} />
124	      </div>
125	    );
126	  }
127	  // The stored account being checked again: its sign-in may have ended.
128	  const checking = status.phase === 'checking';
129	  return (
130	    <div className="agent-account" data-testid="agent-account">
131	      <div className="agent-row-copy">
132	          <h2 className="agent-account-title">JusPrin account</h2>
133	          <span className={`agent-row-status${checking ? '' : ' agent-row-status--saved'}`} data-testid="agent-account-status">
134	            {checking ? 'Checking your account…' : (
135	              <span className="agent-row-status-label">
136	                <span className="jp-icon jp-icon-check" aria-hidden="true" />
137	                <span>{account.account ? `Signed in as ${account.account}` : 'Signed in'}</span>
138	              </span>
139	            )}
140	          </span>
141	      </div>
142	      {checking ? (
143	        <button type="button" className="link" onClick={actions.cancel}>Cancel</button>
144	      ) : (
145	        <button type="button" className="agent-row-action" onClick={onSignOut}>Sign out</button>
146	      )}
147	      <div className="agent-account-detail">
148	      {!checking && status.error && (
149	        <p className="agent-key-error" role="alert" data-testid="account-error">{status.error.message}</p>
150	      )}
151	      {!checking && status.warning && <p className="agent-row-note">{status.warning}</p>}
152	      </div>
153	    </div>
154	  );
155	}
156	
157	// What is stored for a provider, as its row's status line says it.
158	// 'sessionOnly' is a key that passed its check but could not be written to
159	// this computer: it works until JusPrin restarts.
160	export type KeyStanding = 'none' | 'saved' | 'rejected' | 'sessionOnly';
161	
162	// The row's key form. 'unreachable' is a check that never got an answer, so
163	// the key stays locked for another try; 'refused' is one the provider
164	// answered no to, so the key stays open to correct.
165	export type KeyForm = 'closed' | 'entering' | 'checking' | 'unreachable' | 'refused';
166	
167	const STANDING_LINE: Record<Exclude<KeyStanding, 'none'>, { icon: string; text: string }> = {
168	  saved: { icon: 'check', text: 'Key saved on this computer' },
169	  sessionOnly: { icon: 'triangle-alert', text: 'This key works now, but JusPrin couldn’t save it.' },
170	  rejected: { icon: 'circle-alert', text: 'The provider rejected this key' },
171	};
172	
173	// A key being checked stays visible so it is clear which one is in question,
174	// but only its known start: the rest is never echoed back.
175	function maskedKey(key: string, prefix: string): string {
176	  return `${key.startsWith(prefix) ? prefix : ''}${'•'.repeat(16)}`;
177	}
178	
179	export interface ProviderKeyRowProps {
180	  provider: ProviderOption;
181	  standing: KeyStanding;
182	  // The host's start-and-last-4 hint of the stored key; never the key.
183	  hint?: string;
184	  form: KeyForm;
185	  error?: string;
186	  value: string;
187	  // Another check is running; nothing else may start until it ends.
188	  busy: boolean;
189	  pasteAvailable: boolean;
190	  inputRef: RefObject<HTMLInputElement>;
191	  onChange: (value: string) => void;
192	  onOpen: () => void;
193	  onRemove: () => void;
194	  onCheck: () => void;
195	  onCancel: () => void;
196	  onPaste: () => void;
197	}
198	
199	export function ProviderKeyRow({
200	  provider, standing, hint, form, error, value, busy, pasteAvailable, inputRef,
201	  onChange, onOpen, onRemove, onCheck, onCancel, onPaste,
202	}: ProviderKeyRowProps) {
203	  const name = provider.label;
204	  const replacing = form !== 'closed' && standing !== 'none';
205	  const locked = form === 'checking' || form === 'unreachable';
206	  const fieldId = `agent-key-${provider.id}`;
207	  const line = standing === 'none' ? null : STANDING_LINE[standing];
208	  const keyDown = (event: KeyboardEvent<HTMLInputElement>) => {
209	    if (event.key === 'Enter' && value.trim()) onCheck();
210	    if (event.key === 'Escape') onCancel();
211	  };
212	
213	  return (
214	    <div className="agent-row" data-testid={`agent-key-${provider.id}`}>
215	      <div className="agent-row-line">
216	        <div className="agent-row-copy">
217	          <span className="agent-row-name">{name}</span>
218	          {line ? (
219	            <span className={`agent-row-status agent-row-status--${standing}`} data-testid={`agent-key-${provider.id}-standing`}>
220	              <span className="agent-row-status-label">
221	                <span className={`jp-icon jp-icon-${line.icon}`} aria-hidden="true" />
222	                <span>{line.text}</span>
223	              </span>
224	              {hint && <code className="agent-key-hint">{hint}</code>}
225	            </span>
226	          ) : (
227	            <span className="agent-row-status">No key</span>
228	          )}
229	        </div>
230	        {form === 'closed' && (standing === 'none' ? (
231	          <button type="button" className="agent-row-action" onClick={onOpen} disabled={busy}
232	            aria-label={`Add ${name} key`}>
233	            <span className="jp-icon jp-icon-plus" aria-hidden="true" />
234	            Add key
235	          </button>
236	        ) : (
237	          <div className="agent-row-actions">
238	            <button type="button" className="agent-row-action" onClick={onOpen} disabled={busy}
239	              aria-label={`Replace ${name} key`}>Replace</button>
240	            <button type="button" className="agent-row-action agent-row-action--danger" onClick={onRemove} disabled={busy}
241	              aria-label={`Remove ${name} key`}>Remove</button>
242	          </div>
243	        ))}
244	      </div>
245	
246	      {form !== 'closed' && (
247	        <div className="agent-key-form">
248	          <label className="agent-key-label" htmlFor={fieldId}>{replacing ? `New ${name} key` : `${name} API key`}</label>
249	          <div className={`agent-key-field${locked ? ' agent-key-field--locked' : error ? ' agent-key-field--error' : ''}`}>
250	            {locked ? (
251	              <input id={fieldId} className="agent-key-input" value={maskedKey(value, provider.prefix)} disabled readOnly />
252	            ) : (
253	              <input
254	                ref={inputRef}
255	                id={fieldId}
256	                type="password"
257	                className="agent-key-input"
258	                placeholder={replacing ? 'Paste the new key' : `Paste your ${name} key (${provider.prefix}…)`}
259	                value={value}
260	                aria-invalid={error ? true : undefined}
261	                onChange={(event) => onChange(event.target.value)}
262	                onKeyDown={keyDown}
263	              />
264	            )}
265	            {!locked && pasteAvailable && (
266	              <button type="button" className="link" onClick={onPaste}>Paste</button>
267	            )}
268	          </div>
269	          {error && <p className="agent-key-error" role="alert" data-testid="setup-error">{error}</p>}
270	          <div className="agent-key-actions">
271	            {form === 'checking' ? (
272	              <span className="agent-key-checking">Checking with {name}…</span>
273	            ) : (
274	              <button type="button" className="primary" onClick={onCheck} disabled={!value.trim()}>Check key</button>
275	            )}
276	            <button type="button" className="link" onClick={onCancel}>Cancel</button>
277	            {replacing && form !== 'checking' && hint && (
278	              <span className="agent-key-keeps">Keeps <code>{hint}</code> until the new key passes</span>
279	            )}
280	          </div>
281	        </div>
282	      )}
283	
284	      {form === 'closed' && standing === 'sessionOnly' && (
285	        <p className="agent-row-note">
286	          You’ll need to add it again after JusPrin restarts.
287	        </p>
288	      )}
289	      {form === 'closed' && standing === 'rejected' && (
290	        <p className="agent-row-note">Replace it with a working key, or remove it.</p>
291	      )}
292	    </div>
293	  );
294	}
295	
296	// A check that never reached the provider says nothing about the key.
297	const UNREACHED = new Set(['network_error', 'timeout', 'service_unavailable', 'service_overloaded', 'setup_failed']);
298	
299	export interface ProviderKeysProps {
300	  // Preferences lists the ways one under another and names each one.
301	  heading?: boolean;
302	  setup: SetupStatusPayload;
303	  // Providers with a stored key, by hint; the key itself never reaches the page.
304	  savedKeys: SavedKeyInfo[];
305	  onCheck: (provider: string, apiKey: string) => void;
306	  onCancel: () => void;
307	  onRemove: (provider: string) => void;
308	}
309	
310	// One row per provider. At most one row has its form open: the host checks
311	// one key at a time, and a key typed into one row means nothing to another.
312	export function ProviderKeys({ heading = false, setup, savedKeys, onCheck, onCancel, onRemove }: ProviderKeysProps) {
313	  const [open, setOpen] = useState<string | null>(null);
314	  const [key, setKey] = useState('');
315	  // The open form's key has been sent, so the host's status now speaks for
316	  // it. Typing again makes it a different key that nothing has said anything
317	  // about yet.
318	  const [sent, setSent] = useState(false);
319	  const [pasteAvailable, setPasteAvailable] = useState(false);
320	  const input = useRef<HTMLInputElement>(null);
321	
322	  // Clipboard reads are not granted in every embedded web view; the paste
323	  // shortcut appears only where it will actually work. Typing and the
324	  // platform's own paste always do.
325	  useEffect(() => {
326	    setPasteAvailable(
327	      typeof navigator !== 'undefined' && !!navigator.clipboard && typeof navigator.clipboard.readText === 'function',
328	    );
329	  }, []);
330	
331	  const close = () => {
332	    setOpen(null);
333	    setKey('');
334	    setSent(false);
335	  };
336	
337	  // A key that passes becomes the provider's key (or works until restart),
338	  // so its form has nothing left to do.
339	  useEffect(() => {
340	    if (setup.phase === 'verified') close();
341	  }, [setup.phase]);
342	
343	  useEffect(() => {
344	    if (open) input.current?.focus();
345	  }, [open]);
346	
347	  const busy = setup.phase === 'checking';
348	
349	  const formFor = (provider: ProviderOption): KeyForm => {
350	    if (open !== provider.id) return 'closed';
351	    if (sent && setup.provider === provider.id) {
352	      if (setup.phase === 'checking') return 'checking';
353	      if (setup.phase === 'error') return UNREACHED.has(setup.error?.code ?? '') ? 'unreachable' : 'refused';
354	    }
355	    return 'entering';
356	  };
357	
358	  const errorFor = (provider: ProviderOption, form: KeyForm): string | undefined => {
359	    if (form === 'unreachable') return `Couldn’t reach ${provider.label} to check this key. Nothing was saved. Try again.`;
360	    if (form !== 'refused') return undefined;
361	    if (setup.error?.code === 'invalid_credentials') return `${provider.label} rejected this key. Nothing was saved.`;
362	    return `${setup.error?.message ?? 'The key could not be checked.'} Nothing was saved.`;
363	  };
364	
365	  const paste = () => {
366	    navigator.clipboard
367	      .readText()
368	      .then((text) => {
369	        setKey(text.trim());
370	        setSent(false);
371	        input.current?.focus();
372	      })
373	      .catch(() => {
374	        // Refused at the OS or view level: leave the field alone and let the
375	        // user paste the way they always could.
376	        input.current?.focus();
377	      });
378	  };
379	
380	  return (
381	    <section className="agent-group" aria-label="Your own API key">
382	      <div className="agent-group-head">
383	        {heading && <h2 className="agent-group-title">Your own API key</h2>}
384	        <p className="agent-group-intro">Billed by your provider, not JusPrin. Stored on this computer only.</p>
385	      </div>
386	      {PROVIDERS.map((provider) => {
387	        const saved = savedKeys.find((candidate) => candidate.provider === provider.id);
388	        const sessionOnly = setup.phase === 'verified' && !!setup.warning && setup.provider === provider.id;
389	        // A key that could not be stored has no hint: the host never kept it.
390	        const standing: KeyStanding = sessionOnly ? 'sessionOnly' : saved ? (saved.rejected ? 'rejected' : 'saved') : 'none';
391	        const form = formFor(provider);
392	        return (
393	          <ProviderKeyRow
394	            key={provider.id}
395	            provider={provider}
396	            standing={standing}
397	            hint={sessionOnly ? undefined : saved?.hint}
398	            form={form}
399	            error={errorFor(provider, form)}
400	            value={open === provider.id ? key : ''}
401	            busy={busy}
402	            pasteAvailable={pasteAvailable}
403	            inputRef={input}
404	            onChange={(value) => {
405	              setKey(value);
406	              setSent(false);
407	            }}
408	            onOpen={() => {
409	              setOpen(provider.id);
410	              setKey('');
411	              setSent(false);
412	            }}
413	            onRemove={() => onRemove(provider.id)}
414	            onCheck={() => {
415	              if (!key.trim() || busy) return;
416	              setSent(true);
417	              onCheck(provider.id, key.trim());
418	            }}
419	            onCancel={() => {
420	              if (form === 'checking') onCancel();
421	              close();
422	            }}
423	            onPaste={paste}
424	          />
425	        );
426	      })}
427	      <div className="agent-group-foot">
428	        <p className="agent-row-note">Every chat can pick a model from these providers in its message box.</p>
429	      </div>
430	    </section>
431	  );
432	}
433	
434	export interface ToolRowProps {
435	  tool: McpToolInfo;
436	  onConnect: () => void;
437	}
438	
439	// "Found" is only what JusPrin could see on disk: the app or its settings
440	// file. Any tool can be connected, found or not.
441	export function ToolRow({ tool, onConnect }: ToolRowProps) {
442	  return (
443	    <div className="agent-row" data-testid={`agent-tool-${tool.id}`}>
444	      <div className="agent-row-line">
445	        <div className="agent-row-copy">
446	          <span className="agent-row-name">
447	            {tool.name}
448	            {tool.subtitle && <span className="agent-row-detail">{tool.subtitle}</span>}
449	          </span>
450	          <span className="agent-row-status">{tool.detected ? 'Found on this computer' : 'Not found on this computer'}</span>
451	        </div>
452	        <button type="button" className="agent-row-action" aria-label={`Connect ${tool.name}`} onClick={onConnect}>
453	          Connect…
454	        </button>
455	      </div>
456	    </div>
457	  );
458	}
459	
460	export interface ToolGroupProps {
461	  heading?: boolean;
462	  tools: McpToolInfo[];
463	  onConnect: (tool: McpToolInfo) => void;
464	  onLookAgain: () => void;
465	}
466	
467	export function ToolGroup({ heading = false, tools, onConnect, onLookAgain }: ToolGroupProps) {
468	  return (
469	    <section className="agent-group" aria-label="Connect an AI tool you already use">
470	      <div className="agent-group-head">
471	        {heading && <h2 className="agent-group-title">Connect an AI tool you already use</h2>}
472	        <p className="agent-group-intro">
473	          Let an AI app on this computer, such as Claude Desktop, work with the open project. JusPrin adds itself to
474	          that app’s settings.
475	        </p>
476	      </div>
477	      {tools.map((tool) => <ToolRow key={tool.id} tool={tool} onConnect={() => onConnect(tool)} />)}
478	      <div className="agent-group-foot">
479	        <p className="agent-row-note">
480	          “Found” means JusPrin found the app or its settings file here, not that the app is signed in. You can connect
481	          one that wasn’t found.
482	        </p>
483	        <button type="button" className="agent-row-action" onClick={onLookAgain}>
484	          <span className="jp-icon jp-icon-refresh-cw" aria-hidden="true" />
485	          Look again
486	        </button>
487	      </div>
488	    </section>
489	  );
490	}
491

