{
    if (!m_setup)
        return;
    pump_account();
    std::optional<SetupOutcome> outcome = m_setup->poll();
    if (!outcome)
        return;

    if (!outcome->ok) {
        send_setup_status("error", {}, outcome->elapsed_ms, outcome->error);
        m_setup_pending.reset();
