from lib.view_helpers import get_printer_or_404
from lib.file_storage import save_file_obj
from app.models import Print, Printer, FirstLayerInspection, FirstLayerInspectionImage, GCodeFile
from config.celery import celery_app
from lib import gcode_metadata

from api.serializers import PrinterSerializer, FirstLayerInspectionSerializer, FirstLayerInspectionImageSerializer
from .serializers import UserMessageSerializer, SubscriptionSerializer, SubscriptionExtraSerializer, \
    PublicTimelapseSerializer, UploadedTimelapseSerializer, UserExtSerializer, PrinterExtSerializer, PrinterExtensionSerializer, DetectiveHourCouponCodeSerializer, UserExtensionSerializer
from .models import PrinterExtension, UserMessage, Subscription, PublicTimelapse, UploadedTimelapse, \
    AccountDeletionReason, can_account_be_deleted, DetectiveHourCouponCode, UserExtension
from .lib.utils import user_oversubcribed_num, get_subscription_extra, user_active_subscription, LEGACY_PRICING_PLAN_IDS

FIRST_LAYER_INSPECTION_DEDUPE_TTL_SECS = 6 * 60 * 60
MAX_NOZZLE_CAM_PIC_BYTES = 5 * 1024 * 1024

class UserMessageViewSet(viewsets.ModelViewSet):
    permission_classes = (IsAuthenticated,)
    serializer_class = UserMessageSerializer

    def get_queryset(self):
        return UserMessage.objects.filter(Q(user=self.request.user), Q(shown=False), Q(expire_at__isnull=True) | Q(expire_at__gt=timezone.now()))

    @action(detail=True, methods=['get'])
    def dismiss(self, request, pk=None):
        self.get_queryset().filter(pk=pk).update(shown=True)
        return Response({'result': 'ok'})


class EntUserViewSet(UserViewSet):
    serializer_class = UserExtSerializer

    @action(detail=False, methods=['post'])
    def delete(self, request):
        reason = request.data['reason'][:1024]
        AccountDeletionReason.objects.create(
            user_id=request.user.id,
            reason=reason,
        )
        request.user.delete()

        return Response(status=status.HTTP_204_NO_CONTENT)

    @action(detail=False, methods=['get', 'patch'])
    def me_ext(self, request):
        if request.method == 'PATCH':
            user_ext, _ = UserExtension.objects.get_or_create(user=request.user)
            serializer = UserExtensionSerializer(user_ext, data=request.data, partial=True)
            if serializer.is_valid(raise_exception=True):
                serializer.save()
                return Response(serializer.data)
        serializer = self.serializer_class(request.user, many=False)
        return Response(serializer.data)

    @action(detail=False, methods=['post'])
    def switch_legacy_subscription_to_loyalty(self, request):
        sub = user_active_subscription(request.user)
        if not sub or sub.plan_id not in LEGACY_PRICING_PLAN_IDS:
            return Response(
                {'error': 'Only active legacy Pro subscriptions can switch to loyalty pricing.'},
                status=status.HTTP_400_BAD_REQUEST,
            )
        if sub.external_id:
            target_plan = '{}-loyalty'.format(sub.plan_id)
            result = chargebee.Subscription.update(sub.external_id, {
                'plan_id': target_plan,
                'end_of_term': False,
                'prorate': False,
            })
            with transaction.atomic():
                sub.plan_id = target_plan
                sub.external_resource_version = str(result.subscription.resource_version)
                sub.save(update_fields=['plan_id', 'external_resource_version'])
        return Response(SubscriptionSerializer(sub).data)


class SubscriptionViewSet(mixins.ListModelMixin,
                          viewsets.GenericViewSet):
    permission_classes = (IsAuthenticated,)
    serializer_class = SubscriptionSerializer

        return self.active()

    def is_in_pro_trial(self):
        return self.plan_id == 'pro-trial' and self.active()

    def update_pro_status_on_user(self):
        self.user.is_pro = self.is_pro()
        self.user.save()


def can_account_be_deleted(user, sub=None):
    sub = sub if sub is not None else Subscription.objects.get(user=user)
    return (
        (sub.is_in_pro_trial() or not sub.is_pro()) and
        not PrepaidDHPackPlaceholder.objects.filter(user=user).exists()
    )


class PrepaidDHPackPlaceholder(models.Model):
    user = models.OneToOneField(User, on_delete=models.CASCADE, null=False)
    external_id = models.CharField(max_length=40, null=False, blank=False)
    external_user_id = models.CharField(max_length=40, null=False, blank=False)

    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)


class DetectiveHourTransaction(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE, null=False)
    description = models.CharField(max_length=1024, null=False, blank=False)
    hours = models.FloatField(null=False)
    reference_id = models.CharField(max_length=50, db_index=True, null=True, blank=True)
    forfeitable = models.BooleanField(null=False, blank=False)

    created_at = models.DateTimeField(auto_now_add=True, db_index=True)
    updated_at = models.DateTimeField(auto_now=True)


class DetectiveHourCouponCode(models.Model):
    code = models.CharField(max_length=1024, null=False, blank=False, db_index=True)
    redeemed_by = models.ForeignKey(User, on_delete=models.SET_NULL, null=True, blank=True)
from django.apps import AppConfig


class JusprinConfig(AppConfig):
    default_auto_field = 'django.db.models.BigAutoField'
    name = 'jusprin'
    label = 'jusprin'
    verbose_name = 'JusPrin'

    def ready(self):
        from django.db.models.signals import post_delete
        from app.models import User
        post_delete.connect(forget_kept_chats, sender=User, dispatch_uid='jusprin_forget_kept_chats')


def forget_kept_chats(sender, instance, **kwargs):
    """A deleted account's kept chats are deleted too, however it was deleted
    (the account page, the admin)."""
    from django.db import transaction
    from config.celery import celery_app
    user_id = instance.id
    transaction.on_commit(lambda: celery_app.send_task(
        'app_ent.tasks.jusprin_tasks.forget_jusprin_chats', args=[user_id]))backend/app/views/web_views.py:102:def delete_printer(request, pk=None):

