1	// JusPrin's Preferences window (canvas "JusPrin v2", Preferences, decided
2	// 2026-10-21): a list of sections on the left and the chosen one beside it.
3	// The app reads and writes every setting, under the keys OrcaSlicer's own
4	// dialog uses, and sends what is stored after each change; the page only
5	// says what to change. Account holds the JusPrin account and is where every
6	// surface that finds no AI opens it; BYOAI (Bring Your Own AI) holds the
7	// person's own API keys and AI tools, with no JusPrin account in it. Both draw
8	// the connection rows of AgentConnection.tsx.
9	
10	import { useEffect, useState } from 'react';
11	import {
12	  AccountStatusPayload,
13	  CreditAccount,
14	  DragAction,
15	  McpCatalogPayload,
16	  McpPreviewPayload,
17	  McpStatusPayload,
18	  McpToolInfo,
19	  ModelCatalogPayload,
20	  PreferencesPayload,
21	  PreferencesSection,
22	  SavedKeyInfo,
23	  SetupStatusPayload,
24	} from '../bridge/protocol';
25	import { AccountBox } from './AccountBox';
26	import { AccountRow, ProviderKeys, ToolGroup } from './AgentConnection';
27	import type { SignInActions } from './SignInDoor';
28	import { balanceRows, EXPIRING_FIRST, showsExpiringFirst } from './BalancePanel';
29	import { creditCount, creditNumber, MESSAGE_PRICES, TIER_NAMES } from '../credits';
30	import { MarkdownMessage } from './MarkdownMessage';
31	import { Progress } from './Progress';
32	import { ActionMenu } from './ChatNavigation';
33	import { SetupLocalTool } from './SetupLocalTool';
34	
35	// A hint is a second, smaller line under the label, for a label that needs it.
36	const SECTIONS: { id: PreferencesSection; label: string; hint?: string; icon: string }[] = [
37	  { id: 'account', label: 'Account', icon: 'user' },
38	  { id: 'agent', label: 'BYOAI', hint: 'Bring Your Own AI', icon: 'key' },
39	  { id: 'appearance', label: 'Appearance', icon: 'palette' },
40	  { id: 'view3d', label: '3D view', icon: 'box' },
41	  { id: 'projects', label: 'Projects & files', icon: 'folder' },
42	  { id: 'updates', label: 'Updates', icon: 'refresh-cw' },
43	];
44	
45	// What each mouse button's drag can do, in OrcaSlicer's order.
46	const DRAG_ACTIONS: { value: DragAction; label: string }[] = [
47	  { value: 'rotate', label: 'Turn the view' },
48	  { value: 'pan', label: 'Pan' },
49	  { value: 'none', label: 'Nothing' },
50	];
51	
52	export interface PreferencesActions {
53	  // One setting, by the name the app's settings use.
54	  set: (name: string, value: string | boolean) => void;
55	  // A command: choose_downloads, show_versions, open_update, check_updates,
56	  // skip_update (with the version), restart, orca_preferences.
57	  run: (action: string, details?: Record<string, string>) => void;
58	  checkKey: (provider: string, apiKey: string) => void;
59	  cancelCheck: () => void;
60	  removeKey: (provider: string) => void;
61	  refreshTools: () => void;
62	  previewTool: (toolId: string) => void;
63	  connectTool: (toolId: string) => void;
64	  revealTool: (toolId: string) => void;
65	  // The JusPrin account's sign-in, as every screen that signs in has it.
66	  signIn: SignInActions;
