253	          <span className="prefs-note">in the last 30 days</span>
254	        </div>
255	        <div className="prefs-usage-chart">
256	          <div className="prefs-usage-bars">
257	            {days.map((day) => {
258	              const credits = byDay.get(day) ?? 0;
259	              return <div key={day} className="prefs-usage-bar" title={`${dayLabel(day)}: ${creditCount(credits)}`}
260	                style={{ height: `${most > 0 ? (credits / most) * 100 : 0}%` }} />;
261	            })}
