// the keys setup stored and the providers' own model lists; without one every
// chat uses the agent the host was given.
class IChatModelSource
{
public:
    virtual ~IChatModelSource() = default;
    // Providers with a stored key, in setup's order.
    virtual std::vector<std::string> configured_providers() const = 0;
    // The provider a chat without a choice of its own talks to.
    virtual std::string default_provider() const = 0;
    // A ready agent for this choice, or nullptr when its provider has no key.
    virtual AgentServicePtr make_agent(const ChatModelChoice& choice) = 0;
    // Asks the provider for its models; `done` is called later, once, on the
    // thread the host runs on, and not at all after the source is replaced.
    // `refused` says the provider turned the stored key or sign-in down (401
    // or 403); any other failure says nothing about it.
    using ModelsDone = std::function<void(bool ok, std::vector<ModelOption> models, bool refused)>;
    virtual void list_models(const std::string& provider, ModelsDone done) = 0;
    // For an account provider, the wire format the account's model list last
    // gave this model; empty when it gave none, and for other providers.
    virtual std::string model_format(const std::string& provider, const std::string& model) const
    {
        (void) provider;
        (void) model;
        return {};
    }
    // The signed-in account's credits, plan and usage, later, on the host's
    // thread; nothing when no account is signed in or it could not be read.
    using AccountDone = std::function<void(std::optional<nlohmann::json> account)>;
    virtual void fetch_account(AccountDone done) { done(std::nullopt); }
    // The HTML the JusPrin server puts in the box on Preferences › Account,
    // later, on the host's thread; nothing when it sends none or could not be
    // asked. Asked with the account's token when one is signed in.
    using AccountBoxDone = std::function<void(std::optional<std::string> html)>;
    virtual void fetch_account_box(AccountBoxDone done) { done(std::nullopt); }
};

class AgentHost
{
public:
    using SendFn = std::function<void(const std::string& envelope_json)>;

    AgentHost(Workspace::IWorkspace& workspace,
              ProjectPersistence&    persistence,
              AgentAvailability      availability,
              bool                   dark_appearance,
              AgentServicePtr        agent = {},
              AgentSetupServicePtr   setup = {});
    ~AgentHost();

    AgentHost(const AgentHost&) = delete;
    AgentHost& operator=(const AgentHost&) = delete;

    void set_send(SendFn send);

    // -- Sessions with a subject of their own --------------------------------
    // The host is the project's conversation unless an owner says otherwise.
    // A panel whose conversation is about something else -- the printer panel
    // on Home -- supplies the four things that differ: what the model is told
    // and may call, the turn that opens the conversation, the page messages of
    // its own surface, and the state its surface pins above the thread.

    // Stamped on every request this host makes.
    // A session with tools of its own saves its own presets; in the project
    // chat the person saves one, from the card the Agent's preview proposes.
    // The surface the person opens the next project from, for the line a
    // reopened calibration test starts with.
    void set_project_opened_from(std::string surface) { m_opened_from = std::move(surface); }
    // The calibration project just opened (by the app after the popup, or by
    // calibration_generate from the person's own project): it is marked as
    // one, its chat is named for it and opens with the handover line, and,
    for (const ModelOption& option : held->second.models)
        if (option.id == choice.model)
            return option.images;
    return true;
}

void AgentHost::request_account()
{
    if (!m_model_source)
        return;
    m_model_source->fetch_account([this](std::optional<json> account) {
        // One that could not be read keeps the last answer; signing out clears it.
        const std::vector<std::string> configured = m_model_source->configured_providers();
        const bool signed_in = std::any_of(configured.begin(), configured.end(), [](const std::string& provider) {
            const ProviderProfile* profile = profile_for(provider);
            return profile != nullptr && profile->account_sign_in;
        });
        if (account)
            m_account = std::move(account);
        else if (!signed_in)
            m_account.reset();
        else
            return;
        send_account();
        send_active_chat_model();
    });
}

void AgentHost::send_account()
{
    if (m_handshake)
        send_envelope(Protocol::kAccount,
                      json{{"account", m_account ? *m_account : json()}, {"chatTitles", usage_chat_titles()}}.dump());
}

void AgentHost::request_account_box()
{
    // Signing in or out asks again, so only the latest request is answered.
    const unsigned request = ++m_account_box_request;
    auto answer = [this, request](std::optional<std::string> html) {
        if (request == m_account_box_request && m_handshake)
            send_envelope(Protocol::kAccountBox, json{{"html", html ? json(*html) : json()}}.dump());
    };
    if (m_model_source)
        m_model_source->fetch_account_box(std::move(answer));
    else
        answer(std::nullopt);
}

