        return make_provider_agent(*served, key, choice.model, {}, make_openai_http_transport(), logging_listeners());
    }

    std::string model_format(const std::string& provider, const std::string& model) const override
    {
        return stored_format(m_config, provider, model);
    }

    void fetch_account(AccountDone done) override
    {
        for (const std::string& provider : configured_providers()) {
            const ProviderProfile* profile = profile_for(provider);
            if (profile == nullptr || !profile->account_sign_in)
                continue;
            Agent::fetch_account(*profile, load_provider_api_key(m_config, provider), endpoint_for(m_config, *profile), m_cancelled,
                                 [post = m_post, done = std::move(done)](std::optional<nlohmann::json> account) {
                                     post([done, account = std::move(account)]() mutable { done(std::move(account)); });
                                 });
            return;
        }
        done(std::nullopt);
    }

    // Signed out, the server is asked with no token: it then offers sign-up.
    void fetch_account_box(AccountBoxDone done) override
    {
        const std::string url = cloud_server_from_gateway(endpoint_for(m_config, account_provider())) + "/ent/jusprin/v2/account_box";
        Agent::fetch_account_box(account_provider(), cloud_account_token(m_config), url, m_cancelled,
                                 [post = m_post, done = std::move(done)](std::optional<std::string> html) {
                                     post([done, html = std::move(html)]() mutable { done(std::move(html)); });
                                 });
    }

    void list_models(const std::string& provider, ModelsDone done) override
    {
        const ProviderProfile* profile = profile_for(provider);
        const std::string      key     = load_provider_api_key(m_config, provider);
        if (profile == nullptr || key.empty()) {
            done(false, {}, false);
            return;
        }
        fetch_model_list(*profile, key, endpoint_for(m_config, *profile), m_cancelled,
                         [post = m_post, done = std::move(done), provider, config = m_config,
                          account = profile->account_sign_in](ModelListResult result) {
