old='''void fetch_model_list(const ProviderProfile& profile'''
new='''void delete_account(const ProviderProfile& profile, const std::string& token, const std::string& url,
                    std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(bool)> done)
{
    auto finished = std::make_shared<std::function<void(bool)>>(std::move(done));
    auto http     = Slic3r::Http::del(url);
    http.header("Authorization", "Bearer " + token);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.tls_verify(true)
        .timeout_connect(10)
        .timeout_max(60)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete([cancelled, finished](std::string, unsigned status) {
            if (!*cancelled)
                (*finished)(status == 204);
        })
        .on_error([cancelled, finished](std::string, std::string, unsigned) {
            if (!*cancelled)
