void AgentHost::handle_delete_account(const std::string& envelope_id)
{
    const auto answer = [this, envelope_id](bool deleted) {
        if (m_handshake)
            send_envelope(Protocol::kAccountDeleted, json{{"deleted", deleted}}.dump(), envelope_id);
