// --server-sheet: the server's pages in the app's sheet, and Delete account,
// against a real server: the one JUSPRIN_SERVER_URL names, signed in with the
// token in JUSPRIN_TEST_ACCOUNT_TOKEN (never printed). It deletes that
// account, so the token must be a throwaway account's on a test server.
//
// On Preferences › Account, Get more credits opens the sheet signed in through
// a page link and loads the server's page; the page going to the done address
// closes the sheet. Delete account, confirmed, deletes the account on the
// server and signs out of it.

    void verify_server_sheet()
    {
        const char* server = std::getenv("JUSPRIN_SERVER_URL");
        const char* token  = std::getenv("JUSPRIN_TEST_ACCOUNT_TOKEN");
        if (server == nullptr || *server == '\0' || token == nullptr || *token == '\0') {
            std::cout << "HARNESS SERVER SHEET needs JUSPRIN_SERVER_URL and JUSPRIN_TEST_ACCOUNT_TOKEN" << std::endl;
            check(false, "server_sheet_has_a_server_and_an_account");
            finish();
            return;
        }
        AppConfig* config = wxGetApp().app_config;
        config->set("jusprin_agent", "jusprin_api_key", std::string(token));
        config->set("jusprin_agent", "jusprin_account", std::string("server-sheet@example.com"));
        config->set("jusprin_agent", "provider", std::string("jusprin"));
        config->set("jusprin_agent", "enabled", std::string("true"));
        config->set("jusprin_agent", "cloud_consent", std::string("true"));

        struct Seen
        {
            int         step{0};
            bool        opened{false};
            std::string probe;
            std::string sheet_url;
            bool        sheet_closed{false};
            bool        signed_out{false};
        };
        auto seen     = std::make_shared<Seen>();
        auto deadline = std::make_shared<std::chrono::steady_clock::time_point>(std::chrono::steady_clock::now() + 90s);
        const std::string done_url = std::string(server) + "/ent/jusprin/v2/web/done";
        // What the Account page shows, as the page's title: whether Get more
        // credits and Delete account are there, and the confirmation's button.
        const char* probe =
            "(function () { var b = Array.from(document.querySelectorAll('button')).map(function (x) { return x.textContent; });"
            " document.title = 'account:' + (b.indexOf('Get more credits') >= 0 ? 'more' : '-') + ':'"
            " + (b.indexOf('Delete account…') >= 0 ? 'delete' : '-') + ':'"
            " + (document.querySelector('[role=dialog]') ? 'dialog' : '-'); })()";
        const auto click = [](wxWebView* view, const std::string& text) {
            WebView::RunScript(view, wxString::FromUTF8(
                "Array.from(document.querySelectorAll('button')).find(function (x) { return x.textContent === '" + text +
                "'; }).click()"));
        };
        // The sheet is modal over Preferences, and the harness asks about each
        // modal window in turn: the sheet is left open, and either one's turn
        // drives the steps, which run on the Preferences page.
        m_modal_gate = [this, seen, deadline, done_url, probe, click](wxDialog& dialog) {
            if (dynamic_cast<ServerSheet*>(&dialog) == nullptr && dynamic_cast<Preferences::PreferencesWindow*>(&dialog) == nullptr)
                return true;
            Preferences::PreferencesWindow* window = nullptr;
            for (wxWindow* top : wxTopLevelWindows)
                if (auto* found = dynamic_cast<Preferences::PreferencesWindow*>(top))
                    window = found;
            if (window == nullptr)
                return false;
            const bool preferences_turn = &dialog == window;
            seen->opened = true;
            if (std::chrono::steady_clock::now() > *deadline)
                return preferences_turn;
            if (!window->page_connected())
                return false;
            wxWebView* page = window->web_view().webview();
            const std::string title = page->GetCurrentTitle().ToUTF8().data();
            if (title != seen->probe)
                std::cout << "HARNESS SERVER SHEET step " << seen->step << " " << title << std::endl;
            seen->probe = title;
            ServerSheet* sheet = ServerSheet::current();
            switch (seen->step) {
            case 0:
                // The account's credits have arrived when Get more credits shows.
                if (title.rfind("account:more", 0) == 0) {
                    click(page, "Get more credits");
                    seen->step = 1;
                }
                break;
            case 1:
                if (sheet != nullptr && sheet->state() == ServerSheet::State::Page) {
                    if (!m_state->capture_dir.empty())
                        blit_screen(sheet->GetScreenRect(), "server-sheet");
                    seen->sheet_url = sheet->web_view()->GetCurrentURL().ToUTF8().data();
                    // What the server's checkout ends in.
                    WebView::RunScript(sheet->web_view(), wxString::FromUTF8("location.href = '" + done_url + "'"));
                    seen->step = 2;
                }
                break;
            case 2:
                if (sheet == nullptr) {
                    seen->sheet_closed = true;
                    click(page, "Delete account…");
                    seen->step = 3;
                }
                break;
            case 3:
                if (title.find(":dialog") != std::string::npos) {
                    if (!m_state->capture_dir.empty())
                        blit_screen(window->GetScreenRect(), "delete-account");
                    click(page, "Delete account");
                    seen->step = 4;
                }
                break;
            default:
                if (title.rfind("account:-:-:-", 0) == 0 && Agent::cloud_account_token(wxGetApp().app_config).empty()) {
                    seen->signed_out = true;
                    return preferences_turn;
                }
            }
            WebView::RunScript(page, probe);
            return false;
        };
        m_modals_before = m_modals_answered;
        answer_modals(wxID_CANCEL);
        installed_shell()->request_preferences("account");
        auto gone = [seen] {
            if (!seen->opened)
                return false;
            for (wxWindow* window : wxTopLevelWindows)
                if (dynamic_cast<Preferences::PreferencesWindow*>(window) != nullptr)
                    return false;
            return true;
        };
        wait_until(gone, "server_sheet_preferences_closed", [self = shared_from_this(), seen] {
            self->stop_answering_modals();
            // The page's address without the one-time link or a query.
            const std::string page = seen->sheet_url.substr(0, seen->sheet_url.find('?'));
            std::cout << "HARNESS SERVER SHEET page " << page << " closed=" << seen->sheet_closed
                      << " signed_out=" << seen->signed_out << std::endl;
            self->check(seen->step >= 2 && page.size() > 0 && page.find("/ent/jusprin/v2/web/prices") != std::string::npos,
                        "server_sheet_opens_the_prices_page_signed_in");
            self->check(seen->sheet_url.find("from=account") != std::string::npos, "server_sheet_says_where_the_click_was");
            self->check(seen->sheet_closed, "server_sheet_closes_at_the_done_address");
            self->check(seen->signed_out, "delete_account_deletes_and_signs_out");
            self->finish();
        });
    }

#pragma once

// One of the JusPrin server's pages in a sheet over the window that opened it
// (the canvas's "Plan and billing" boards): Credits and plans, or Billing and
// usage. Anything about dollars, payment or changing a plan is drawn by the
// server, so a price change never needs a release; the app draws only the
// sheet's title row and its loading and can't-load states.
//
// The page opens signed in as the app's account: the app asks the server for
// a link that signs in once (POST /ent/jusprin/v2/web_link) and loads it.
// Open in browser asks for a fresh link and opens it in the person's browser,
// for their saved cards or password manager. When the page goes to the done
// address (/ent/jusprin/v2/web/done) the sheet closes. However it closes,
// `closed` runs, so the opener reads the account again: a purchase may have
// finished without reaching the done address.
//
// The sheet is modal: Preferences is itself a modal window, and on macOS a
// window opened over a modal one without its own modal loop gets no clicks.

#include <wx/dialog.h>
#include <wx/timer.h>

#include <functional>
#include <memory>
#include <string>

class Button;
class wxPanel;
class wxStaticText;
class wxWebView;
class wxWebViewEvent;

namespace Slic3r::GUI::JusPrin {

class HeaderButton;
class ShellTheme;

class ServerSheet final : public wxDialog
{
public:
    // Shows `page` ("prices" or "billing") over `parent` and returns once the
    // sheet has closed, after `closed`. `from` says where in the app the click
    // was.
    static void open(wxWindow* parent, const std::string& page, const std::string& from, std::function<void()> closed);
    // The open sheet, or nullptr; for the shell harness.
    static ServerSheet* current();

    // What the sheet shows in place of the page: nothing, a loading line, or
    // that the page could not be loaded, with Try again.
    enum class State { Page, Loading, Failed };
    State state() const { return m_state; }
    wxWebView* web_view() const { return m_view; }

private:
    ServerSheet(wxWindow* parent, const ShellTheme& theme);
    ~ServerSheet() override;

    void     show_page(const std::string& page, const std::string& from);
    wxWindow* build_header();
    void     load();
    // Asks the server for a link to the page; `use` gets it, or an empty one.
    void     request_link(std::function<void(std::string url)> use);
    void     open_in_browser();
    void     set_state(State state);
    void     on_navigating(wxWebViewEvent& event);
    void     on_loaded(wxWebViewEvent& event);
    void     on_error(wxWebViewEvent& event);
    void     close();
    void     release();

    const ShellTheme&     m_theme;
    wxPanel*              m_body{nullptr};
    wxStaticText*         m_title{nullptr};
    HeaderButton*         m_browser{nullptr};
    HeaderButton*         m_close{nullptr};
    wxWebView*            m_view{nullptr};
    wxPanel*              m_status{nullptr};
    wxStaticText*         m_status_title{nullptr};
    wxStaticText*         m_status_detail{nullptr};
    Button*               m_retry{nullptr};
    wxTimer               m_load_deadline{this};
    wxTimer               m_release_timer{this};
    State                 m_state{State::Loading};
    std::string           m_page;
    std::string           m_from;
    // A link request answered after the sheet moved on, or closed, is dropped.
    unsigned              m_request{0};
    std::shared_ptr<bool> m_alive{std::make_shared<bool>(true)};
    bool                  m_closing{false};
};

} // namespace Slic3r::GUI::JusPrin

#pragma once

// Asks a provider for its model list over HTTP. Kept apart from
// ModelCatalog.cpp, which only reads the answer, because this needs Orca's
// Http client and the GUI-free host tests do not link it.

#include "ModelCatalog.hpp"

#include <atomic>
#include <functional>
#include <memory>
#include <optional>
#include <string>

#include <nlohmann/json.hpp>

namespace Slic3r::GUI::JusPrin::Agent {

struct ModelListResult
{
    bool                     ok{false};
    std::vector<ModelOption> models;
    bool                     refused{false}; // answered 401 or 403
    std::string              error; // for the log; the page shows its own words
};

// Fetches every page of the list on Http's own thread and calls `done` there
// once. Setting `*cancelled` stops it; `done` is then not called.
// The signed-in account's credits, plan and usage; nothing when they could not
// be read. `done` runs on the request's thread.
void fetch_account(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                   std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<nlohmann::json>)> done);

// The HTML of the box on Preferences › Account, from the account's server at
// `url`, sent with `token` when there is one; nothing when the server sends
// none or cannot be reached. `done` runs on the request's thread.
void fetch_account_box(const ProviderProfile& profile, const std::string& token, const std::string& url,
                       std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<std::string>)> done);

// Deletes the account `token` signs in as, with DELETE at `url`; `done` says
// whether the server answered that it did (204), on the request's thread.
void delete_account(const ProviderProfile& profile, const std::string& token, const std::string& url,
                    std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(bool)> done);

void fetch_model_list(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                      std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(ModelListResult)> done);

} // namespace Slic3r::GUI::JusPrin::Agent

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

